INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7450023, 1179161, 16148, '<td valign="top">Beautiful centre jour!  I like the tilted composition but wish there was a little more definition in the person walking their dog.  One of my favorites in the challenge.</td>', 'Beautiful centre jour!  I like the tilted composition but wish there was a little more definition in the person walking their dog.  One of my favorites in the challenge.', '2016-04-13 10:08:15.000000', NULL, 1),
(7450024, 1179336, 16148, '<td valign="top">Interesting shapes and patterns!  I''m thinking black and white would take this to the next level?  Probably just how I view the world.  Nice!</td>', 'Interesting shapes and patterns!  I''m thinking black and white would take this to the next level?  Probably just how I view the world.  Nice!', '2016-04-13 10:14:21.000000', NULL, 1),
(7450025, 1179380, 16148, '<td valign="top">Dramatic!  In the spirit of the challenge, your tilt and POV conveys an uneasy feeling.</td>', 'Dramatic!  In the spirit of the challenge, your tilt and POV conveys an uneasy feeling.', '2016-04-13 10:17:31.000000', NULL, 1),
(7450026, 1179231, 16148, '<td valign="top">Stairs are a natural choice for this challenge.  You''ve managed to keep it simple and fresh.  Well done!</td>', 'Stairs are a natural choice for this challenge.  You''ve managed to keep it simple and fresh.  Well done!', '2016-04-13 10:19:28.000000', NULL, 1),
(7450027, 1179275, 12611, '<td valign="top">Nice contrasty abstract</td>', 'Nice contrasty abstract', '2016-04-13 10:19:59.000000', NULL, 1),
(7450028, 1179161, 12611, '<td valign="top">Nice message. and dark and light at the same time.</td>', 'Nice message. and dark and light at the same time.', '2016-04-13 10:21:55.000000', NULL, 1),
(7450030, 1179150, 12611, '<td valign="top">Nice detail</td>', 'Nice detail', '2016-04-13 10:24:44.000000', NULL, 1),
(7450032, 1179331, 12611, '<td valign="top">I like the simple tilt and the storybook feel, which adds a whimsical mood. The muted colors add to the fantasy. Very subtle. Nice work.</td>', 'I like the simple tilt and the storybook feel, which adds a whimsical mood. The muted colors add to the fantasy. Very subtle. Nice work.', '2016-04-13 10:30:13.000000', NULL, 1),
(7450033, 1179316, 12611, '<td valign="top">Nice use of the tilt, and interestingly, a very well highlighted and detailed focal point...</td>', 'Nice use of the tilt, and interestingly, a very well highlighted and detailed focal point...', '2016-04-13 10:32:39.000000', NULL, 1),
(7450036, 1179321, 12611, '<td valign="top">The blur and the great blue hues create tension and bleakness. I am not usually a conventionalist, but perhaps making the focal point in a more golden ratio position, rather than dead center, might add <i>even more</i> unease and <i>even more</i> drama to the shot- adding a heightened sense of foreboding to the stillness before the storm.</td>', 'The blur and the great blue hues create tension and bleakness. I am not usually a conventionalist, but perhaps making the focal point in a more golden ratio position, rather than dead center, might add even more unease and even more drama to the shot- adding a heightened sense of foreboding to the stillness before the storm.', '2016-04-13 10:38:58.000000', NULL, 1),
(7450038, 1179090, 12611, '<td valign="top">people wont dig the blur and focus issues, although they help the feeling of confusion. What I like is the feel of a puff of smoke in the focal point.</td>', 'people wont dig the blur and focus issues, although they help the feeling of confusion. What I like is the feel of a puff of smoke in the focal point.', '2016-04-13 10:42:11.000000', NULL, 1),
(7450040, 1179383, 12611, '<td valign="top">The lines, blur and grain all work, they leave the viewer uneasy at best.</td>', 'The lines, blur and grain all work, they leave the viewer uneasy at best.', '2016-04-13 10:47:23.000000', NULL, 1),
(7450041, 1179381, 12611, '<td valign="top">beautiful seat tone gradations. terrific light.</td>', 'beautiful seat tone gradations. terrific light.', '2016-04-13 10:47:54.000000', NULL, 1),
(7450079, 1179381, 96751, '<td valign="top">Oooh, feels like an astronaut waiting for liftoff! Maybe he''s too close to the edge...?</td>', 'Oooh, feels like an astronaut waiting for liftoff! Maybe he''s too close to the edge...?', '2016-04-13 14:23:31.000000', NULL, 1),
